let count = 0;
for (let byte of data) {
  if (count === 0) {
    if ((byte >> 5) === 0b110) count = 1;
    else if ((byte >> 4) === 0b1110) count = 2;
    else if ((byte >> 3) === 0b11110) count = 3;
    else if ((byte >> 7) !== 0) return false;
  } else {
    if ((byte >> 6) !== 0b10) return false;
    count--;
  }
}
return count === 0;
